// Demonstrating encapsulation conceptually in JavaScript
// Each 'layer' wraps the payload from the layer above

function applicationLayer(message) {
  // HTTP — application data
  return { httpBody: message, headers: { 'Content-Type': 'text/plain' } };
}

function transportLayer(appData, srcPort, dstPort) {
  // TCP segment: adds port numbers and sequence info
  return { segment: appData, srcPort, dstPort, seq: Math.floor(Math.random() * 65535) };
}

function networkLayer(segment, srcIP, dstIP) {
  // IP packet: adds IP addresses and TTL
  return { packet: segment, srcIP, dstIP, ttl: 64 };
}

function dataLinkLayer(packet, srcMAC, dstMAC) {
  // Ethernet frame: adds MAC addresses + simulated checksum
  const payload = JSON.stringify(packet);
  const checksum = payload.split('').reduce((acc, c) => acc ^ c.charCodeAt(0), 0);
  return { frame: packet, srcMAC, dstMAC, checksum };
}

// Sender encapsulation — data travels DOWN the stack
const appData  = applicationLayer('Hello, World!');
const segment  = transportLayer(appData, 54321, 80);
const packet   = networkLayer(segment, '192.168.1.5', '93.184.216.34');
const frame    = dataLinkLayer(packet, 'AA:BB:CC:DD:EE:FF', 'FF:EE:DD:CC:BB:AA');

console.log('Frame checksum:', frame.checksum);
console.log('Destination IP:', frame.frame.dstIP);
console.log('Destination port:', frame.frame.packet.dstPort);
console.log('App body:', frame.frame.packet.segment.httpBody);

// ── OSI Layer Quick Reference ────────────────────────────────
//
// Layer | Name         | PDU     | Key protocols      | Devices
// ------|--------------|---------|--------------------|-----------
//   7   | Application  | Data    | HTTP, DNS, FTP     | Firewall L7
//   6   | Presentation | Data    | TLS/SSL, JPEG, gzip| -
//   5   | Session      | Data    | RPC, NetBIOS       | -
//   4   | Transport    | Segment | TCP, UDP, SCTP     | Load balancer L4
//   3   | Network      | Packet  | IP, ICMP, BGP      | Router
//   2   | Data Link    | Frame   | Ethernet, 802.11   | Switch
//   1   | Physical     | Bit     | Cat6, Fibre, 5G    | Hub, NIC

// ── Encapsulation sizes (approximate per layer) ──────────────
const ETHERNET_HEADER = 14; // bytes  (src MAC, dst MAC, EtherType)
const IP_HEADER       = 20; // bytes  (min, without options)
const TCP_HEADER      = 20; // bytes  (min, without options)
const HTTP_OVERHEAD   = 200; // bytes  (typical request headers)

// Total overhead for a 1-byte payload sent over TCP/IP:
const totalOverhead = ETHERNET_HEADER + IP_HEADER + TCP_HEADER + HTTP_OVERHEAD;
console.log(`Overhead for 1 byte payload: ${totalOverhead} bytes`); // 254 bytes

// ── Mnemonic (OSI bottom to top) ─────────────────────────────
// "Please Do Not Throw Sausage Pizza Away"
